"""Text output (Results window, console, logs).

All output goes through `Output`, which keeps the current column (needed for
_column() and _continue) and passes the pieces on to the registered listeners:
the Results window of the interface, the console and log files.

Styles follow Stata's categories: "text", "result", "error",
"input" and "command" (echo of the typed command).
"""

from __future__ import annotations

import contextlib

from typing import Callable

Listener = Callable[[str, str], None]

STYLES = ("text", "result", "error", "input", "command")


class Output:
    def __init__(self) -> None:
        self._listeners: list[Listener] = []
        self.column = 0           # current column (0 = start of the line)
        self.quiet_depth = 0      # > 0 inside quietly
        self.noisy_depth = 0      # noisily inside quietly
        self.capture_depth = 0    # > 0 inside capture: silences even errors
        self.linesize = lambda: 0   # the session's linesize; echoed lines wrap at it

    # -- ouvintes -------------------------------------------------------
    def add_listener(self, fn: Listener) -> None:
        self._listeners.append(fn)

    def remove_listener(self, fn: Listener) -> None:
        if fn in self._listeners:
            self._listeners.remove(fn)

    @contextlib.contextmanager
    def quietly(self):
        """Silences everything inside, even when an enclosing noisily is active (as a nested
        quietly does in Stata)."""
        self.quiet_depth += 1
        saved = self.noisy_depth
        self.noisy_depth = 0
        try:
            yield
        finally:
            self.quiet_depth -= 1
            self.noisy_depth = saved

    # -- silence state -----------------------------------------------
    @property
    def suppressed(self) -> bool:
        return self.quiet_depth > 0 and self.noisy_depth == 0

    # -- escrita -----------------------------------------------------------
    def write(self, text: str, style: str = "text", *, force: bool = False) -> None:
        if not text:
            return
        if force:
            # error messages appear under quietly, but not under capture
            if self.capture_depth > 0 and self.noisy_depth == 0:
                return
        elif self.suppressed:
            return
        for fn in list(self._listeners):
            fn(text, style)
        last_nl = text.rfind("\n")
        if last_nl == -1:
            self.column += len(text)
        else:
            self.column = len(text) - last_nl - 1

    def newline(self, n: int = 1, *, force: bool = False) -> None:
        self.write("\n" * n, "text", force=force)

    def ensure_line_start(self, *, force: bool = False) -> None:
        if self.column != 0:
            self.newline(force=force)

    def error(self, message: str, rc: int, *, show_rc: bool = True,
              hint: list[tuple[str, str]] = ()) -> None:
        """Error message and r(#); — shown even under quietly (but not
        under capture). `hint`: OpenDTA's explanation as (text, style) pieces, between the two."""
        self.ensure_line_start(force=True)
        if message:
            self.write(message + "\n", "error", force=True)
        for text, style in hint:
            self.write(text, style, force=True)
        if show_rc:
            self.write(f"r({rc});\n", "error", force=True)

    def echo_command(self, lines) -> None:
        """Echo '. command' as the Results window does; continuation lines
        appear with '> '."""
        if isinstance(lines, str):
            lines = (lines,)
        self.ensure_line_start()
        w = self.linesize() - 2
        for k, line in enumerate(lines):
            prefix = ". " if k == 0 else "> "
            while w > 0 and len(line) > w:
                self.write(prefix + line[:w] + "\n", "command")
                line, prefix = line[w:], "> "
            self.write(prefix + line + "\n", "command")

    def end_command(self) -> None:
        """Blank line after each command (as in Stata)."""
        self.ensure_line_start()
        self.write("\n")


class Capture:
    """Listener that accumulates the text (used in tests and in batch mode)."""

    def __init__(self) -> None:
        self.parts: list[tuple[str, str]] = []

    def __call__(self, text: str, style: str) -> None:
        self.parts.append((text, style))

    @property
    def text(self) -> str:
        return "".join(t for t, _ in self.parts)

    def clear(self) -> None:
        self.parts.clear()

files.opendta/core/storage.py:
"""Native storage of numeric variables.

Each variable is kept in memory in its own type, with 1 byte per value for byte,
2 for int, 4 for long and float, 8 for double, as in Stata. Missing values use the
same encoding as the .dta format, which makes reading and writing files a
direct copy:

    byte   int8     .  = 101,         .a..z = 102..127
    int    int16    .  = 32741,       .a..z = 32742..32767
    long   int32    .  = 2147483621,  .a..z = 2147483622..2147483647
    float  float32  .  = bits 0x7f000000, .a..z = + k * 0x800
    double float64  the same codes used in the rest of OpenDTA (missing.py)

Computations stay in float64: `decode` produces the float64 vector with
OpenDTA's missing codes and `encode` goes the other way.
"""

from __future__ import annotations

import numpy as np

from . import missing as M

DTYPE = {"byte": np.dtype(np.int8), "int": np.dtype(np.int16), "long": np.dtype(np.int32),
         "float": np.dtype(np.float32), "double": np.dtype(np.float64)}
INT_MISS = {"byte": 101, "int": 32741, "long": 2147483621}
INT_RANGES = {"byte": (-127, 100), "int": (-32767, 32740), "long": (-2147483647, 2147483620)}
FLOAT_MISS_BITS = 0x7F000000
FLOAT_MISS_STEP = 0x00000800
FLOAT_MAX = 1.7014117331926443e38   # largest non-missing float (bits 0x7effffff)

_DBL_BASE = np.uint64(0x7FE0000000000000)
_DBL_SHIFT = np.uint64(40)                 # step of 0x0000010000000000 between .a, .b, ...
_CODES = np.array([M.SYSMISS] + [M.EXTENDED[c] for c in "abcdefghijklmnopqrstuvwxyz"])


def _missing_index(v: np.ndarray, miss: np.ndarray) -> np.ndarray:
    """0 for '.', 1..26 for .a..z (unknown values become '.')."""
    bits = v[miss].view(np.uint64)
    k = ((bits - _DBL_BASE) >> _DBL_SHIFT).astype(np.int64)
    known = (k >= 0) & (k <= 26) & (bits == _DBL_BASE + (k.astype(np.uint64) << _DBL_SHIFT))
    return np.where(known, k, 0)


def encode(values, vtype: str) -> np.ndarray:
    """float64 (OpenDTA codes) -> vector in the native type.

    Values outside the type's range become '.', and non-integers are truncated
    toward zero, as in fit_numeric; values normally arrive already
    adjusted."""
    v = np.asarray(values, dtype=np.float64)
    if vtype == "double":
        return np.array(v, dtype=np.float64, copy=True)
    miss = (v >= M.SYSMISS) | (v != v)
    if vtype == "float":
        over = ~miss & (np.abs(v) > FLOAT_MAX)
        out = np.where(miss | over, 0.0, v).astype(np.float32)
        allmiss = miss | over
        if allmiss.any():
            idx = np.zeros(len(v), dtype=np.int64)
            if miss.any():
                idx[miss] = _missing_index(np.where(v != v, M.SYSMISS, v), miss)
            bits = out.view(np.uint32)
            bits[allmiss] = (FLOAT_MISS_BITS + idx[allmiss] * FLOAT_MISS_STEP).astype(np.uint32)
        return out
    lo, hi = INT_RANGES[vtype]
    over = ~miss & ((v < lo) | (v > hi))
    allmiss = miss | over
    out = np.where(allmiss, 0.0, v).astype(DTYPE[vtype])
    if allmiss.any():
        idx = np.zeros(len(v), dtype=np.int64)
        if miss.any():
            idx[miss] = _missing_index(np.where(v != v, M.SYSMISS, v), miss)
        out[allmiss] = (INT_MISS[vtype] + idx[allmiss]).astype(DTYPE[vtype])
    return out


def decode(raw: np.ndarray, vtype: str) -> np.ndarray:
    """Vector in the native type -> float64 with OpenDTA's missing codes."""
    if vtype == "double":
        return np.array(raw, dtype=np.float64, copy=True)
    v = raw.astype(np.float64)
    if vtype == "float":
        bits = raw.view(np.uint32)
        # only the positive values above the largest valid float; with the sign bit (bit 31) it is
        # a number
        miss = (bits >= FLOAT_MISS_BITS) & (bits < 0x80000000)
        if miss.any():
            k = ((bits[miss] - FLOAT_MISS_BITS) // FLOAT_MISS_STEP).astype(np.int64).clip(0, 26)
            v[miss] = _CODES[k]
        return v
    base = INT_MISS[vtype]
    miss = raw >= base
    if miss.any():
        v[miss] = _CODES[(raw[miss].astype(np.int64) - base).clip(0, 26)]
    return v


def decode_one(x, vtype: str) -> float:
    """A single value (list, Data Browser, sequential replace): without creating vectors."""
    if vtype == "double":
        return float(x)
    if vtype == "float":
        bits = int(np.float32(x).view(np.uint32))
        if FLOAT_MISS_BITS <= bits < 0x80000000:
            return float(_CODES[min((bits - FLOAT_MISS_BITS) // FLOAT_MISS_STEP, 26)])
        return float(x)
    k = int(x)
    base = INT_MISS[vtype]
    return float(k) if k < base else float(_CODES[min(k - base, 26)])


def encode_one(x: float, vtype: str):
    return encode(np.array([x], dtype=np.float64), vtype)[0]


def missing_raw(vtype: str):
    """Native value of '.' in the type."""
    return encode_one(M.SYSMISS, vtype)

files.opendta/core/varlist.py:
"""Varlist expansion (manual [U] 11.4).

    mpg            exact name
    mp             abbreviation (if `set varabbrev on`, the default)
    m*  *g  m?g    wildcards: * (zero or more), ? (exactly one)
    m~             like *, but must match a single variable
    make-weight    range, in dataset order
    _all  or  *    all variables
"""

from __future__ import annotations

import re

from .dataset import Dataset
from .errors import StataError

_WILD = re.compile(r"[*?~]")


def _pattern(token: str) -> re.Pattern[str]:
    out = []
    for ch in token:
        if ch in "*~":
            out.append(".*")
        elif ch == "?":
            out.append(".")
        else:
            out.append(re.escape(ch))
    return re.compile("^" + "".join(out) + "$")


def resolve_name(ds: Dataset, token: str, *, abbrev: bool = True) -> str:
    names = ds.names
    if token in names:
        return token
    if abbrev:
        matches = [n for n in names if n.startswith(token)]
        if len(matches) == 1:
            return matches[0]
        if len(matches) > 1:
            raise StataError(111, f"{token} ambiguous abbreviation")
    raise StataError(111, f"variable {token} not found")


def expand(ds: Dataset, text: str, *, abbrev: bool = True, allow_empty: bool = True) -> list[str]:
    t = re.sub(r"\s*-\s*", "-", text.strip())
    if not t:
        if allow_empty:
            return []
        raise StataError(100, "varlist required")
    out: list[str] = []
    for token in t.split():
        if token in ("_all", "*"):
            out.extend(ds.names)
            continue
        if "-" in token and not token.startswith("-"):
            a, b = token.split("-", 1)
            ia = ds.index(resolve_name(ds, a, abbrev=abbrev))
            ib = ds.index(resolve_name(ds, b, abbrev=abbrev))
            if ib < ia:
                raise StataError(198, f"{token}: variables out of order")
            out.extend(ds.names[ia:ib + 1])
            continue
        if _WILD.search(token):
            pat = _pattern(token)
            matches = [n for n in ds.names if pat.match(n)]
            if not matches:
                raise StataError(111, f"variable {token} not found")
            if "~" in token and len(matches) > 1:
                raise StataError(111, f"{token} ambiguous abbreviation")
            out.extend(matches)
            continue
        out.append(resolve_name(ds, token, abbrev=abbrev))
    return out


def unique(names: list[str]) -> list[str]:
    seen: list[str] = []
    for n in names:
        if n not in seen:
            seen.append(n)
    return seen

files.opendta/estimation/numerics.py:
"""set numerics stata|precise (OpenDTA).

stata (default): computations follow Stata, including its rounding
(normal equations in regress, D.x stored as float, ml stopping criteria).

precise: the same estimates, computed more exactly:
  * regress solved by QR decomposition (the error grows with κ(X), not κ(X)²);
  * D.x and S.x computed and kept in double;
  * ml and optimize() take one more Newton step after converging;
  * optimize()'s numerical derivatives with Richardson extrapolation;
  * generate, egen, input... create double variables when the default type is float.
compare.py and the format tests use stata.
"""

_STATE = {"precise": False}


def set_precise(on: bool) -> None:
    _STATE["precise"] = bool(on)


def precise() -> bool:
    return _STATE["precise"]

files.opendta/lang/expr.py:
"""Expressions: tokenization, parsing (Pratt) and evaluation.

Precedence, from strongest to weakest (manual [U] 13.2.5):

    !  (or ~)          logical negation
    ^                  power (left-associative)
    -                  unary minus
    /  *
    -  +
    != ~= > < >= <= == relational
    &
    |

Missing-value rules: any arithmetic operation with missing gives `.`;
in comparisons, missing is greater than any number (. < .a < ... < .z);
in a logical context, every value other than 0 is true, including missing.

This evaluator is scalar. The vectorized evaluator (lang/vexpr.py) operates
on vectors (one position per observation) for generate/replace/if.
"""

from __future__ import annotations

import math
import re
from dataclasses import dataclass, field
from typing import Any, Callable, Protocol

from ..core import missing as M
from ..core.errors import StataError, syntax_error, type_mismatch

Value = Any  # float or str

# ---------------------------------------------------------------------------
# Tokens
# ---------------------------------------------------------------------------


@dataclass(frozen=True)
class Tok:
    kind: str   # num, str, name, op, end
    value: Any
    pos: int


_NUM = re.compile(r"(?:\d+\.?\d*|\.\d+)(?:[eE][+-]?\d+)?")
_MISS = re.compile(r"\.([a-z])?(?![A-Za-z0-9_])")
_NAME = re.compile(r"[A-Za-z_][A-Za-z0-9_]*")
# time-series operators in an expression: L.y, L2.y, D.y, LD.y ([U] 13.9)
_TSNAME = re.compile(r"(?:(?:[LFDS]\d*)+\.)+[A-Za-z_][A-Za-z0-9_]*")
_OPS = ("==", "!=", "~=", ">=", "<=", "+", "-", "*", "/", "^", "!", "~",
        ">", "<", "&", "|", "(", ")", "[", "]", ",", "=")


def tokenize(text: str, *, stop_on_unknown: bool = False) -> list[Tok]:
    """With stop_on_unknown=True, an unknown character ends the list of
    tokens (used by display and by `if exp command`)."""
    toks: list[Tok] = []
    i, n = 0, len(text)
    while i < n:
        c = text[i]
        if c in " \t\r\n":
            i += 1
            continue
        if c == '"':
            j = text.find('"', i + 1)
            if j == -1:
                raise StataError(198, "unmatched quote")
            toks.append(Tok("str", text[i + 1:j], i))
            i = j + 1
            continue
        if text.startswith('`"', i):
            depth, j = 1, i + 2
            while j < n and depth:
                if text.startswith('`"', j):
                    depth += 1
                    j += 2
                elif text.startswith("\"'", j):
                    depth -= 1
                    j += 2
                else:
                    j += 1
            if depth:
                raise StataError(198, "unmatched quote")
            toks.append(Tok("str", text[i + 2:j - 2], i))
            i = j
            continue
        m = _NUM.match(text, i)
        if m and (c.isdigit() or (c == "." and i + 1 < n and text[i + 1].isdigit())):
            toks.append(Tok("num", float(m.group(0)), i))
            i = m.end()
            continue
        if c == ".":
            m = _MISS.match(text, i)
            if m:
                toks.append(Tok("num", M.missing_code(m.group(0)), i))
                i = m.end()
                continue
        m = _TSNAME.match(text, i) or _NAME.match(text, i)
        if m:
            toks.append(Tok("name", m.group(0), i))
            i = m.end()
            continue
        for op in _OPS:
            if text.startswith(op, i):
                toks.append(Tok("op", op, i))
                i += len(op)
                break
        else:
            if stop_on_unknown:
                toks.append(Tok("end", None, i))
                return toks
            raise syntax_error()
    toks.append(Tok("end", None, n))
    return toks


# ---------------------------------------------------------------------------
# Syntax tree
# ---------------------------------------------------------------------------


@dataclass
class Node:
    pass


@dataclass
class Num(Node):
    value: float


@dataclass
class Str(Node):
    value: str


@dataclass
class Name(Node):
    name: str


@dataclass
class Call(Node):
    name: str
    args: list[Node] = field(default_factory=list)
    raw: str = ""  # raw text of the argument (r(), e(), c())


@dataclass
class Subscript(Node):
    name: str
    index: Node | str
    index2: Node | None = None          # A[i,j]: matrix element


@dataclass
class Unary(Node):
    op: str
    operand: Node


@dataclass
class Binary(Node):
    op: str
    left: Node
    right: Node


_INFIX_BP: dict[str, tuple[int, int]] = {
    "|": (10, 11),
    "&": (20, 21),
    "==": (30, 31), "!=": (30, 31), "~=": (30, 31),
    ">": (30, 31), "<": (30, 31), ">=": (30, 31), "<=": (30, 31),
    "+": (40, 41), "-": (40, 41),
    "*": (50, 51), "/": (50, 51),
    "^": (70, 71),
}
_UMINUS_BP = 60
_NOT_BP = 80

# functions whose argument is a name, not an expression: r(mean), e(N), c(pi)
_RAW_ARG_FUNCS = {"r", "e", "c", "s"}
# _b[x], _se[x]: the index is a name
_RAW_SUBSCRIPTS = {"_b", "_se", "_coef"}


class Parser:
    def __init__(self, text: str, *, stop_on_unknown: bool = False):
        self.text = text
        self.toks = tokenize(text, stop_on_unknown=stop_on_unknown)
        self.i = 0

    # -- utilidades ----------------------------------------------------
    @property
    def tok(self) -> Tok:
        return self.toks[self.i]

    def advance(self) -> Tok:
        t = self.toks[self.i]
        self.i += 1
        return t

    def expect_op(self, op: str) -> None:
        t = self.advance()
        if t.kind != "op" or t.value != op:
            raise syntax_error()

    def at_end(self) -> bool:
        return self.tok.kind == "end"

    @property
    def offset(self) -> int:
        """Position in the text of the next unconsumed token."""
        return self.tok.pos

    # -- grammar -------------------------------------------------------
    def parse_full(self) -> Node:
        node = self.parse_expr()
        if not self.at_end():
            raise syntax_error()
        return node

    def parse_expr(self, min_bp: int = 0) -> Node:
        left = self.parse_prefix()
        while True:
            t = self.tok
            if t.kind != "op" or t.value not in _INFIX_BP:
                if t.kind == "op" and t.value == "=":
                    raise syntax_error()
                break
            lbp, rbp = _INFIX_BP[t.value]
            if lbp < min_bp:
                break
            self.advance()
            right = self.parse_expr(rbp)
            op = "!=" if t.value == "~=" else t.value
            left = Binary(op, left, right)
        return left

    def parse_prefix(self) -> Node:
        t = self.advance()
        if t.kind == "num":
            return Num(t.value)
        if t.kind == "str":
            return Str(t.value)
        if t.kind == "op":
            if t.value == "(":
                node = self.parse_expr()
                self.expect_op(")")
                return node
            if t.value == "-":
                return Unary("-", self.parse_expr(_UMINUS_BP))
            if t.value == "+":
                return Unary("+", self.parse_expr(_UMINUS_BP))
            if t.value in ("!", "~"):
                return Unary("!", self.parse_expr(_NOT_BP))
            raise syntax_error()
        if t.kind == "name":
            return self.parse_name(t)
        raise syntax_error()

    def parse_name(self, t: Tok) -> Node:
        name = t.value
        nxt = self.tok
        if nxt.kind == "op" and nxt.value == "(":
            if name in _RAW_ARG_FUNCS:
                self.advance()
                start = self.tok.pos
                depth = 1
                while depth:
                    tk = self.advance()
                    if tk.kind == "end":
                        raise StataError(132, "too many '(' or '['")
                    if tk.kind == "op" and tk.value == "(":
                        depth += 1
                    elif tk.kind == "op" and tk.value == ")":
                        depth -= 1
                end = self.toks[self.i - 1].pos
                return Call(name, [], raw=self.text[start:end].strip())
            self.advance()
            args: list[Node] = []
            if not (self.tok.kind == "op" and self.tok.value == ")"):
                while True:
                    args.append(self.parse_expr())
                    if self.tok.kind == "op" and self.tok.value == ",":
                        self.advance()
                        continue
                    break
            self.expect_op(")")
            return Call(name, args)
        if nxt.kind == "op" and nxt.value == "[":
            self.advance()
            if name in _RAW_SUBSCRIPTS:
                start = self.tok.pos
                while not (self.tok.kind == "op" and self.tok.value == "]"):
                    if self.tok.kind == "end":
                        raise syntax_error()
                    self.advance()
                raw = self.text[start:self.tok.pos].strip()
                self.advance()
                return Subscript(name, raw)
            idx = self.parse_expr()
            if self.tok.kind == "op" and self.tok.value == ",":
                self.advance()
                idx2 = self.parse_expr()
                self.expect_op("]")
                return Subscript(name, idx, idx2)
            self.expect_op("]")
            return Subscript(name, idx)
        return Name(name)


# functions whose 1st argument is the name of a matrix (see commands/matrix.py)
MATRIX_FUNCS = {"rowsof", "colsof", "el", "trace", "det", "issymmetric", "rownumb",
                "colnumb", "matmissing", "mreldif"}


def parse(text: str) -> Node:
    return Parser(text).parse_full()


# ---------------------------------------------------------------------------
# Evaluation
# ---------------------------------------------------------------------------


class Context(Protocol):
    def resolve_name(self, name: str) -> Value: ...
    def resolve_subscript(self, name: str, index: Any) -> Value: ...
    def resolve_result(self, kind: str, raw: str) -> Value: ...
    def call_function(self, name: str, args: list[Value]) -> Value: ...


def _num(x: float) -> float:
    return M.normalize(x)


def _truth(v: Value) -> bool:
    if isinstance(v, str):
        raise type_mismatch()
    return v != 0


def evaluate(node: Node, ctx: Context) -> Value:
    if isinstance(node, Num):
        return node.value
    if isinstance(node, Str):
        return node.value
    if isinstance(node, Name):
        return ctx.resolve_name(node.name)
    if isinstance(node, Call):
        if node.name in _RAW_ARG_FUNCS:
            return ctx.resolve_result(node.name, node.raw)
        if node.name in MATRIX_FUNCS:
            from ..commands.matrix import matrix_scalar
            return matrix_scalar(ctx.s, node.name, node.args, lambda a: evaluate(a, ctx))
        return ctx.call_function(node.name, [evaluate(a, ctx) for a in node.args])
    if isinstance(node, Subscript):
        if node.index2 is not None:
            from ..commands.matrix import matrix_element
            return matrix_element(ctx.s, node.name, evaluate(node.index, ctx),
                                  evaluate(node.index2, ctx))
        idx = node.index if isinstance(node.index, str) else evaluate(node.index, ctx)
        return ctx.resolve_subscript(node.name, idx)
    if isinstance(node, Unary):
        v = evaluate(node.operand, ctx)
        if node.op == "!":
            return 0.0 if _truth(v) else 1.0
        if node.op == "+":
            if isinstance(v, str):
                # display "a" + "b" ends in error r(198) in Stata
                raise StataError(198, "invalid syntax")
            return v
        if isinstance(v, str):
            raise type_mismatch()
        return M.SYSMISS if M.is_missing(v) else _num(-v)
    if isinstance(node, Binary):
        return _binary(node.op, evaluate(node.left, ctx), evaluate(node.right, ctx))
    raise TypeError(node)


def _binary(op: str, a: Value, b: Value) -> Value:
    if op in ("&", "|"):
        ta, tb = _truth(a), _truth(b)
        return float(ta and tb) if op == "&" else float(ta or tb)

    a_str, b_str = isinstance(a, str), isinstance(b, str)

    # "ab"*3 repete a string
    if op == "*" and a_str != b_str:
        s, n = (a, b) if a_str else (b, a)
        return "" if M.is_missing(n) or n < 1 else s * int(n)

    if a_str != b_str:
        raise type_mismatch()

    if op in _RELATIONAL:
        return 1.0 if _RELATIONAL[op](a, b) else 0.0

    if a_str:
        if op == "+":
            return a + b
        raise type_mismatch()

    if M.is_missing(a) or M.is_missing(b):
        return M.SYSMISS
    try:
        if op == "+":
            return _num(a + b)
        if op == "-":
            return _num(a - b)
        if op == "*":
            return _num(a * b)
        if op == "/":
            return M.SYSMISS if b == 0 else _num(a / b)
        if op == "^":
            return _power(a, b)
    except (OverflowError, ValueError, ZeroDivisionError):
        return M.SYSMISS
    raise syntax_error()


_RELATIONAL: dict[str, Callable[[Any, Any], bool]] = {
    "==": lambda a, b: a == b,
    "!=": lambda a, b: a != b,
    ">": lambda a, b: a > b,
    "<": lambda a, b: a < b,
    ">=": lambda a, b: a >= b,
    "<=": lambda a, b: a <= b,
}


def _power(a: float, b: float) -> float:
    if a == 0 and b == 0:
        return 1.0
    if a < 0 and b != int(b):
        return M.SYSMISS
    if a == 0 and b < 0:
        return M.SYSMISS
    return _num(math.pow(a, b))


class SimpleContext:
    """Minimal context for tests: only constants and functions."""

    def __init__(self, functions: Callable[[str, list[Value]], Value] | None = None):
        self._functions = functions

    def resolve_name(self, name: str) -> Value:
        if name == "_pi":
            return math.pi
        raise StataError(111, f"{name} not found")

    def resolve_subscript(self, name: str, index: Any) -> Value:
        raise StataError(111, f"{name} not found")

    def resolve_result(self, kind: str, raw: str) -> Value:
        return M.SYSMISS

    def call_function(self, name: str, args: list[Value]) -> Value:
        if self._functions is None:
            raise StataError(133, "unknown function " + name + "()")
        return self._functions(name, args)

