"""Splits the text of a do-file into logical command lines.

Rules implemented (manual [U] 16 and [P] comments, #delimit):

* a line whose first non-blank character is `*` is a comment;
* `//` preceded by a space (or at the start of the line) comments to the end of the line;
* `///` preceded by a space joins the next line (continuation);
* `/* ... */` may span lines and may be nested;
* `#delimit ;` switches to `;` as the end of command; `#delimit cr` goes back to
  end of line (the abbreviation `#d` is also accepted). The directive stays in the
  list as the line "#delimit ;" or "#delimit cr", for the echo;
* none of this applies inside "..." or `"..."' strings (compound quotes).
"""

from __future__ import annotations

from dataclasses import dataclass


@dataclass(frozen=True)
class LogicalLine:
    text: str
    lineno: int                  # line (1-based) where the command starts
    raw: tuple[str, ...] = ()    # original physical lines, for the echo
    kind: str = "cmd"            # "cmd", "comment" or "delimit"

    @property
    def echo_lines(self) -> tuple[str, ...]:
        return self.raw or (self.text,)


def _is_delimit(cmd: str) -> str | None:
    """If `cmd` is a #delimit directive, returns 'cr' or ';'."""
    s = cmd.strip()
    if not s.startswith("#d"):
        return None
    head, _, rest = s.partition(" ")
    if not "#delimit".startswith(head) or len(head) < 2:
        return None
    arg = rest.strip()
    if arg == ";":
        return ";"
    if arg == "cr":
        return "cr"
    return None


def split_commands(source: str, *, blanks: bool = False) -> list[LogicalLine]:
    """Whole-line comments (`*` and `//`) also go into the list, with
    kind="comment": Stata echoes them when running a do-file. With `blanks` (do-files), the blank
    lines of the top level go in too, with kind="blank" (Stata echoes them as ". ")."""
    physical = source.replace("\r\n", "\n").replace("\r", "\n").split("\n")
    out: list[LogicalLine] = []
    mode = "cr"
    buf: list[str] = []
    start_line = 0
    line = 1
    i = 0
    n = len(source)
    block = 0        # /* */ depth
    in_str = False   # inside "..."
    compound = 0     # `" "' depth
    nest = [0, False, False]   # { } depth, inside program define ... end, inside mata ... end

    def at_word_start(pos: int) -> bool:
        return pos == 0 or source[pos - 1] in " \t\n\r"

    def raw_lines(first: int, last: int) -> tuple[str, ...]:
        return tuple(ln.rstrip() for ln in physical[first - 1:last])

    def track(text: str) -> None:
        """Nesting of the top level, for the echo of blank lines (only top-level ones echo)."""
        words = text.split()
        first = words[0] if words else ""
        if nest[1] or nest[2]:
            if text == "end":
                nest[1] = nest[2] = False
            return
        if len(first) >= 3 and "program".startswith(first) and not (len(words) > 1 and words[1] in (
                "drop", "dir", "list")):
            nest[1] = True
            return
        if first == "mata" and text.rstrip(":").strip() in ("mata", "mata:"):
            nest[2] = True
            return
        if text.endswith("{"):
            nest[0] += 1
        if text.startswith("}"):
            nest[0] = max(nest[0] - 1, 0)

    def flush() -> None:
        nonlocal buf, start_line, mode
        text = "".join(buf).strip()
        buf = []
        if not text:
            return
        track(text)
        raw = raw_lines(start_line, line)
        if text.startswith("*"):
            out.append(LogicalLine(text, start_line, raw, "comment"))
            return
        new_mode = _is_delimit(text)
        if new_mode is not None:
            mode = new_mode
            out.append(LogicalLine("#delimit " + new_mode, start_line, raw, "delimit"))
            return
        out.append(LogicalLine(text, start_line, raw))

    def note_start() -> None:
        nonlocal start_line
        if not "".join(buf).strip():
            start_line = line

    while i < n:
        c = source[i]

        if block:
            if source.startswith("*/", i):
                block -= 1
                i += 2
                if block == 0:
                    buf.append(" ")
                continue
            if source.startswith("/*", i):
                block += 1
                i += 2
                continue
            if c == "\n":
                line += 1
            i += 1
            continue

        if in_str:
            if c == "\n":
                in_str = False  # unclosed string: the command reports the error
                continue
            buf.append(c)
            if c == '"':
                in_str = False
            i += 1
            continue

        if compound:
            if source.startswith('`"', i):
                compound += 1
                buf.append('`"')
                i += 2
                continue
            if source.startswith("\"'", i):
                compound -= 1
                buf.append("\"'")
                i += 2
                continue
            if c == "\n":
                compound = 0
                continue
            buf.append(c)
            i += 1
            continue

        # outside strings and comments
        if c == "\r":
            i += 1
            continue
        if source.startswith("/*", i):
            block = 1
            i += 2
            continue
        if source.startswith("///", i) and at_word_start(i):
            j = source.find("\n", i)
            if j == -1:
                i = n
            else:
                i = j + 1
                line += 1
            buf.append(" ")
            continue
        if source.startswith("//", i) and at_word_start(i):
            j = source.find("\n", i)
            if not "".join(buf).strip():
                # whole comment line: only for the echo
                out.append(LogicalLine("", line, raw_lines(line, line), "comment"))
            i = n if j == -1 else j
            continue
        if c == "\n":
            current = "".join(buf).strip()
            if (blanks and mode == "cr" and not current and not physical[line - 1].strip() and nest[0] == 0
                    and not nest[1] and not nest[2]):
                # a blank line of the do-file: Stata echoes it as ". " (compat 1920)
                out.append(LogicalLine("", line, ("",), "blank"))
            if mode == "cr" or _is_delimit(current) is not None:
                flush()
            elif current.startswith("*"):
                # * comment in ; mode runs until the next ;
                buf.append(" ")
            else:
                buf.append(" ")
            line += 1
            i += 1
            continue
        if c == ";" and mode == ";":
            flush()
            i += 1
            continue
        note_start()
        if source.startswith('`"', i):
            compound = 1
            buf.append('`"')
            i += 2
            continue
        if c == '"':
            in_str = True
        buf.append(c)
        i += 1

    flush()
    return out

files.opendta/lang/macros.py:
"""Local and global macros and their expansion.

Expansion (manual [U] 18.3 and [P] macro):

* `name'  -> local macro (scope of the running do-file/program)
* $name and ${name} -> global macro
* nested references are resolved from the inside out: ``i''
* `=exp' evaluates the expression; `:function' calls an extended function
* `++i', `i++', `--i', `i--' increment/decrement the local
* a nonexistent macro expands to nothing
* the text resulting from the expansion is not expanded again
* `.obj.member' is the printable form of a class object (lang/classeval.py)
* `"' opens compound quotes and is not treated as a macro reference
"""

from __future__ import annotations

import re
from typing import Callable

from ..core.errors import StataError

_GLOBAL_NAME = re.compile(r"[A-Za-z_][A-Za-z0-9_]{0,31}")


class MacroStore:
    def __init__(self) -> None:
        self.globals: dict[str, str] = {}
        self._frames: list[dict[str, str]] = [{}]

    # -- scope of locals ------------------------------------------------
    @property
    def locals(self) -> dict[str, str]:
        return self._frames[-1]

    def push_frame(self, initial: dict[str, str] | None = None) -> None:
        self._frames.append(dict(initial or {}))

    def pop_frame(self) -> None:
        if len(self._frames) > 1:
            self._frames.pop()

    @property
    def depth(self) -> int:
        return len(self._frames)

    # -- acesso ---------------------------------------------------------------
    def get_local(self, name: str) -> str:
        return self.locals.get(name, "")

    def set_local(self, name: str, value: str) -> None:
        if value == "":
            self.locals.pop(name, None)
        else:
            self.locals[name] = value

    def get_global(self, name: str) -> str:
        return self.globals.get(name, "")

    def set_global(self, name: str, value: str) -> None:
        if value == "":
            self.globals.pop(name, None)
        else:
            self.globals[name] = value

    def clear_globals(self) -> None:
        self.globals.clear()


Resolver = Callable[[str], str]


def expand(text: str, store: MacroStore, *,
           eval_inline: Resolver | None = None,
           extended: Resolver | None = None,
           results: Callable[[str, str], str] | None = None,
           objects: Resolver | None = None) -> str:
    """Expands all macro references in `text`.

    eval_inline receives the text after '=' in `=exp' and returns the resulting string.
    extended receives the text after ':' in `:function' and returns the resulting string.
    """
    s = text
    stack: list[int] = []
    i = 0
    while i < len(s):
        c = s[i]
        if c == "`":
            if i + 1 < len(s) and s[i + 1] == '"':
                i += 2  # aspas compostas
                continue
            stack.append(i)
            i += 1
            continue
        if c == "'" and stack:
            p = stack.pop()
            inner = s[p + 1:i]
            value = _resolve_local(inner, store, eval_inline, extended, results, objects)
            s = s[:p] + value + s[i + 1:]
            i = p + len(value)
            continue
        if c == "$":
            if i + 1 < len(s) and s[i + 1] == "{":
                j = s.find("}", i + 2)
                if j != -1:
                    name = s[i + 2:j]
                    value = store.get_global(name)
                    s = s[:i] + value + s[j + 1:]
                    i += len(value)
                    continue
            m = _GLOBAL_NAME.match(s, i + 1)
            if m:
                value = store.get_global(m.group(0))
                s = s[:i] + value + s[m.end():]
                i += len(value)
                continue
        i += 1
    return s


_RESULT_REF = re.compile(r"^([recs])\(\s*([A-Za-z_][A-Za-z0-9_]*)\s*\)$")


def _resolve_local(inner: str, store: MacroStore,
                   eval_inline: Resolver | None,
                   extended: Resolver | None,
                   results: Callable[[str, str], str] | None = None,
                   objects: Resolver | None = None) -> str:
    stripped = inner.strip()
    if objects is not None and len(stripped) > 1 and stripped[0] == "." and (
            stripped[1].isalpha() or stripped[1] == "_"):
        # `.obj.member': printable form of a class object ([P] class)
        return objects(stripped)
    m = _RESULT_REF.match(stripped)
    if m and results is not None:
        # `r(name)', `e(name)', `s(name)', `c(name)'
        return results(m.group(1), m.group(2))
    if stripped.startswith("="):
        if eval_inline is None:
            raise StataError(198, "invalid syntax")
        return eval_inline(stripped[1:])
    if stripped.startswith(":"):
        if extended is None:
            raise StataError(198, "invalid syntax")
        return extended(stripped[1:].strip())
    for op, delta in (("++", 1), ("--", -1)):
        if stripped.startswith(op) or stripped.endswith(op):
            prefix = stripped.startswith(op)
            name = stripped[2:] if prefix else stripped[:-2]
            current = store.get_local(name)
            try:
                num = float(current) if current else 0.0
            except ValueError:
                raise StataError(198, f"{name} is not a number")
            new = num + delta
            new_s = _num_str(new)
            store.set_local(name, new_s)
            return new_s if prefix else _num_str(num)
    if stripped.startswith("macval(") and stripped.endswith(")"):
        return store.get_local(stripped[7:-1].strip())
    return store.get_local(inner)


def _num_str(x: float) -> str:
    return str(int(x)) if x == int(x) else repr(x)

files.opendta/lang/syntax.py:
"""Standard command syntax (manual [U] 11):

    [by varlist:] command [varlist] [=exp] [if exp] [in range] [weight] [using filename] [, options]

`parse_standard` splits the parts, respecting quotes, parentheses and brackets.
`parse_options` and `match_options` handle options with abbreviations.
`parse_in` converts an `in` range into indices.
"""

from __future__ import annotations

import re
from dataclasses import dataclass, field

from ..core.errors import StataError

_WEIGHT = re.compile(r"^\[\s*(fweight|fw|frequency|aweight|aw|cellsize|pweight|pw|iweight|iw|weight)\s*=\s*(.+?)\s*\]$")
_WEIGHT_NAMES = {"fw": "fweight", "fweight": "fweight", "frequency": "fweight",
                 "aw": "aweight", "aweight": "aweight", "cellsize": "aweight",
                 "pw": "pweight", "pweight": "pweight", "iw": "iweight", "iweight": "iweight",
                 "weight": "weight"}


@dataclass
class Parsed:
    varlist: str = ""
    exp: str | None = None
    if_: str | None = None
    in_: str | None = None
    weight: tuple[str, str] | None = None
    using: str | None = None
    options: str = ""
    has_comma: bool = False


def _scan(text: str):
    """Yields (position, character, depth) outside quotes."""
    depth = 0
    i, n = 0, len(text)
    while i < n:
        c = text[i]
        if text.startswith('`"', i):
            d, j = 1, i + 2
            while j < n and d:
                if text.startswith('`"', j):
                    d += 1
                    j += 2
                elif text.startswith("\"'", j):
                    d -= 1
                    j += 2
                else:
                    j += 1
            i = j
            continue
        if c == '"':
            j = text.find('"', i + 1)
            i = n if j == -1 else j + 1
            continue
        if c in "([":
            depth += 1
        elif c in ")]":
            depth -= 1
        yield i, c, depth
        i += 1


def find_top(text: str, ch: str) -> int:
    for i, c, d in _scan(text):
        if c == ch and d == 0:
            return i
    return -1


def _find_keyword(text: str, word: str) -> int:
    """Position of `word` as a standalone word at the top level (or -1)."""
    for i, c, d in _scan(text):
        if d != 0 or c != word[0]:
            continue
        if not text.startswith(word, i):
            continue
        before = text[i - 1] if i > 0 else " "
        after = text[i + len(word)] if i + len(word) < len(text) else " "
        if before in " \t" and after in " \t(":
            return i
        if i == 0 and after in " \t":
            return i
    return -1


def _find_weight(text: str) -> tuple[int, int]:
    for i, c, d in _scan(text):
        if c == "[" and d == 1:
            j = i
            depth = 0
            for k in range(i, len(text)):
                if text[k] == "[":
                    depth += 1
                elif text[k] == "]":
                    depth -= 1
                    if depth == 0:
                        j = k
                        break
            if _WEIGHT.match(text[i:j + 1]):
                before = text[:i].rstrip()
                # x[_n-1] is a subscript, not a weight
                if before and (before[-1].isalnum() or before[-1] == "_") and not text[i - 1].isspace():
                    continue
                return i, j + 1
    return -1, -1


def _find_assign(text: str) -> int:
    for i, c, d in _scan(text):
        if c != "=" or d != 0:
            continue
        prev = text[i - 1] if i > 0 else ""
        nxt = text[i + 1] if i + 1 < len(text) else ""
        if prev in "=!<>~" or nxt == "=":
            continue
        return i
    return -1


def parse_standard(text: str) -> Parsed:
    p = Parsed()
    t = text.strip()
    comma = find_top(t, ",")
    if comma != -1:
        p.options = t[comma + 1:].strip()
        p.has_comma = True
        t = t[:comma].rstrip()

    # peso
    a, b = _find_weight(t)
    if a != -1:
        m = _WEIGHT.match(t[a:b])
        assert m
        p.weight = (_WEIGHT_NAMES[m.group(1)], m.group(2))
        t = (t[:a] + " " + t[b:]).strip()

    # using, if and in: located and cut from the end toward the start
    marks = []
    for kw in ("using", "if", "in"):
        pos = _find_keyword(" " + t, kw)
        if pos != -1:
            marks.append((pos - 1, kw))
    marks.sort()
    for idx, (pos, kw) in enumerate(marks):
        end = marks[idx + 1][0] if idx + 1 < len(marks) else len(t)
        value = t[pos + len(kw):end].strip()
        if not value:
            raise StataError(198, "invalid syntax")
        if kw == "if":
            p.if_ = value
        elif kw == "in":
            p.in_ = value
        else:
            p.using = value
    head = t[:marks[0][0]].strip() if marks else t

    eq = _find_assign(head)
    if eq != -1:
        p.exp = head[eq + 1:].strip()
        if not p.exp:
            raise StataError(198, "invalid syntax")
        head = head[:eq].strip()
    p.varlist = head
    return p


# ---------------------------------------------------------------------------
# Options
# ---------------------------------------------------------------------------

def parse_options(text: str) -> list[tuple[str, str | None]]:
    out: list[tuple[str, str | None]] = []
    i, n = 0, len(text)
    while i < n:
        while i < n and text[i] in " \t":
            i += 1
        if i >= n:
            break
        m = re.match(r"[A-Za-z_][A-Za-z0-9_]*", text[i:])
        if not m:
            raise StataError(198, "invalid syntax")
        name = m.group(0)
        i += m.end()
        arg = None
        if i < n and text[i] == "(":
            depth, j = 0, i
            while j < n:
                if text[j] == "(":
                    depth += 1
                elif text[j] == ")":
                    depth -= 1
                    if depth == 0:
                        break
                elif text[j] == '"':
                    k = text.find('"', j + 1)
                    j = n - 1 if k == -1 else k
                j += 1
            if depth != 0:
                raise StataError(198, "invalid syntax")
            arg = text[i + 1:j]
            i = j + 1
        out.append((name, arg))
    return out


def match_options(text: str, spec: dict[str, int]) -> dict[str, str | bool]:
    """`spec`: full name -> minimal abbreviation length.
    Returns {full name: argument or True}."""
    result: dict[str, str | bool] = {}
    for name, arg in parse_options(text):
        for full, minimum in spec.items():
            if len(name) >= minimum and full.startswith(name):
                result[full] = arg if arg is not None else True
                break
        else:
            # an option given with an argument is named with () (compat 1501)
            raise StataError(198, f"option {name}{'()' if arg is not None else ''} not allowed",
                             options=list(spec))
    return result


# ---------------------------------------------------------------------------
# in range
# ---------------------------------------------------------------------------

def parse_in(text: str, nobs: int) -> tuple[int, int]:
    """Converts '1/10', 'f/l', '-5/l', '5' into 0-based (start, end), end exclusive."""
    t = text.replace(" ", "")

    def one(tok: str) -> int:
        if tok == "f":
            return 1
        if tok == "l":
            return nobs
        try:
            k = int(float(tok))
        except ValueError:
            raise StataError(198, "invalid syntax")
        if k < 0:
            k = nobs + k + 1
        return k

    if "/" in t:
        a, b = t.split("/", 1)
        lo, hi = one(a), one(b)
    else:
        lo = hi = one(t)
    if lo < 1 or hi > nobs or lo > hi:
        if nobs == 0 and lo == 1:
            return 0, 0
        raise StataError(198, "Obs. nos. out of range")
    return lo - 1, hi


@dataclass
class ByPrefix:
    keys: list[str] = field(default_factory=list)
    sort_extra: list[str] = field(default_factory=list)
    sort: bool = False
    rc0: bool = False


def parse_by(text: str) -> ByPrefix:
    """Parses what comes between 'by' and ':' — 'g1 g2 (t)', ', sort'."""
    t = text.strip()
    bp = ByPrefix()
    comma = find_top(t, ",")
    if comma != -1:
        opts = match_options(t[comma + 1:], {"sort": 1, "rc0": 3})
        bp.sort = bool(opts.get("sort"))
        bp.rc0 = bool(opts.get("rc0"))
        t = t[:comma]
    m = re.search(r"\(([^)]*)\)\s*$", t)
    if m:
        bp.sort_extra = m.group(1).split()
        t = t[:m.start()]
    bp.keys = t.split()
    if not bp.keys:
        raise StataError(100, "varlist required")
    return bp

files.opendta/lang/vexpr.py:
"""Vectorized evaluation of expressions over the observations of the dataset.

The syntax tree is the same as in lang/expr.py. Here each node returns a
scalar (float or str) or a numpy vector with one position per observation:
float64 for numbers (with OpenDTA's missing codes) and object for
strings.

`by` groups: `_n`, `_N` and subscripts such as `x[_n-1]` are relative to the group
of the observation. Without `by`, there is a single group with all observations.
"""

from __future__ import annotations

import math
from typing import TYPE_CHECKING, Any

import numpy as np

from ..core import missing as M
from ..core.errors import StataError, type_mismatch
from . import functions as F
from .expr import (
    _RAW_ARG_FUNCS,
    MATRIX_FUNCS,
    Binary,
    Call,
    Name,
    Node,
    Num,
    Str,
    Subscript,
    Unary,
    _binary,
)

if TYPE_CHECKING:
    from ..session import Session

SYS = M.SYSMISS


# ---------------------------------------------------------------------------
# Grupos
# ---------------------------------------------------------------------------

class Groups:
    def __init__(self, start: np.ndarray, size: np.ndarray):
        self.start = start            # index of the 1st obs of the group, per observation
        self.size = size              # group size, per observation
        n = len(start)
        self.pos = np.arange(n) - start   # 0-based position in the group

    @classmethod
    def single(cls, nobs: int) -> "Groups":
        return cls(np.zeros(nobs, dtype=np.int64), np.full(nobs, nobs, dtype=np.int64))

    @classmethod
    def from_columns(cls, columns: list[np.ndarray]) -> "Groups":
        n = len(columns[0]) if columns else 0
        if n == 0:
            return cls(np.zeros(0, dtype=np.int64), np.zeros(0, dtype=np.int64))
        change = np.zeros(n, dtype=bool)
        change[0] = True
        for col in columns:
            change[1:] |= col[1:] != col[:-1]
        starts = np.flatnonzero(change)
        ends = np.append(starts[1:], n)
        start = np.repeat(starts, ends - starts)
        size = np.repeat(ends - starts, ends - starts)
        return cls(start.astype(np.int64), size.astype(np.int64))

    @property
    def first(self) -> np.ndarray:
        return self.pos == 0

    @property
    def ids(self) -> np.ndarray:
        return np.cumsum(self.first) - 1


# ---------------------------------------------------------------------------
# Type utilities
# ---------------------------------------------------------------------------

def is_str(v: Any) -> bool:
    return isinstance(v, str) or (isinstance(v, np.ndarray) and v.dtype == object)


def is_vec(v: Any) -> bool:
    return isinstance(v, np.ndarray)


def broadcast(v: Any, n: int) -> np.ndarray:
    if is_vec(v):
        return v
    if isinstance(v, str):
        return np.array([v] * n, dtype=object)
    return np.full(n, float(v))


def _num_arr(v: Any) -> np.ndarray | float:
    return v if is_vec(v) else float(v)


def _clean(r: np.ndarray, miss: np.ndarray | bool) -> np.ndarray:
    """Missing inputs, divisions by zero and overflows become `.`."""
    r = np.where(miss, SYS, r)
    bad = ~np.isfinite(r) | (np.abs(r) >= SYS)
    return np.where(bad, SYS, r)


def truth(v: Any) -> Any:
    if is_str(v):
        raise type_mismatch()
    return v != 0


# ---------------------------------------------------------------------------
# Contexto
# ---------------------------------------------------------------------------

def ts_value(s, name: str):
    """L.y, D.y...: the variable's vector with the time-series operators."""
    from ..estimation import fvars
    from ..estimation.fvars import _component_alts
    comps = _component_alts(s.data, name, False)
    if not comps or len(comps) != 1:
        raise StataError(198, "invalid syntax")
    return fvars.comp_values(s.data, comps[0])


class VectorContext:
    def __init__(self, session: "Session", groups: Groups | None = None):
        self.s = session
        self.ds = session.data
        self.n = self.ds.nobs
        self.groups = groups or Groups.single(self.n)

    def name(self, name: str) -> Any:
        ds = self.ds
        if ds.has(name):
            return ds.get(name).data
        if "." in name:
            return ts_value(self.s, name)
        if name in self.s.scalars:
            return self.s.scalars[name]
        if name == "_n":
            return (self.groups.pos + 1).astype(np.float64)
        if name == "_N":
            return self.groups.size.astype(np.float64)
        if name == "_pi":
            return math.pi
        if name == "_rc":
            return float(self.s.rc)
        if self.s.settings.get("varabbrev", "on") == "on":
            matches = [n for n in ds.names if n.startswith(name)]
            if len(matches) == 1:
                return ds.get(matches[0]).data
            if len(matches) > 1:
                raise StataError(111, f"{name} ambiguous abbreviation")
        raise StataError(111, f"{name} not found")

    def subscript(self, name: str, idx: Any) -> Any:
        if name in ("_b", "_se", "_coef"):
            return self.s.context.resolve_subscript(name, idx)
        data = self.name(name)
        if not is_vec(data):
            raise StataError(198, "invalid syntax")
        if is_str(idx):
            raise type_mismatch()
        k = np.trunc(broadcast(idx, self.n))
        g = self.groups
        valid = (k < SYS) & (k >= 1) & (k <= g.size)
        target = np.where(valid, g.start + k.clip(1, None) - 1, 0).astype(np.int64)
        if self.n == 0:
            return data[:0]
        vals = data[target]
        if data.dtype == object:
            return np.where(valid, vals, "").astype(object)
        return np.where(valid, vals, SYS)

    def call(self, name: str, args: list[Any]) -> Any:
        if name == "sum" and len(args) == 1:
            return self._running_sum(args[0])
        if name in _RANDOM:
            return self._random(name, args)
        if not any(is_vec(a) for a in args):
            return F.call(name, args)
        fast = _FAST.get(name)
        if fast is not None:
            out = fast(*args)
            if out is not NotImplemented:
                return out
        if name not in F.FUNCTIONS:
            raise StataError(133, f"unknown function {name}()")
        cols = [broadcast(a, self.n) for a in args]
        results = _elementwise(name, cols, self.n)
        if any(isinstance(r, str) for r in results):
            return np.array(results, dtype=object)
        return np.array(results, dtype=np.float64)

    def _random(self, name: str, args: list[Any]) -> np.ndarray:
        """One draw per observation (only those in the sample in generate/replace)."""
        from ..core import rng
        lo, hi, _ = rng.DISTRIBUTIONS[name]
        if not (lo <= len(args) <= hi):
            raise StataError(198, "invalid syntax")
        if any(is_str(a) for a in args):
            raise type_mismatch()
        mask = getattr(self.s, "_rng_mask", None)
        block = getattr(self.s, "_rng_block", None)
        if block is not None:
            U, j = block
            block[1] = j + 1
            u = U[:, j] if j < U.shape[1] else rng.RNG.uniform(U.shape[0])
            fn = rng.DISTRIBUTIONS[name][2]
            if mask is None or len(mask) != self.n:
                arrs = [np.broadcast_to(np.asarray(broadcast(a, self.n) if is_vec(a) else a, dtype=np.float64),
                                        (self.n,)) for a in args]
                with np.errstate(all="ignore"):
                    return fn(u, *arrs)
            idx = np.flatnonzero(mask)
            out = np.full(self.n, SYS)
            arrs = [np.broadcast_to(np.asarray(broadcast(a, self.n)[idx] if is_vec(a) else a, dtype=np.float64),
                                    (len(idx),)) for a in args]
            with np.errstate(all="ignore"):
                out[idx] = fn(u, *arrs)
            return out
        if mask is None or len(mask) != self.n:
            return rng.draw(name, [broadcast(a, self.n) if is_vec(a) else a for a in args], self.n)
        # only the observations in the sample draw (generate/replace with if/in)
        idx = np.flatnonzero(mask)
        out = np.full(self.n, SYS)
        out[idx] = rng.draw(name, [broadcast(a, self.n)[idx] if is_vec(a) else a for a in args], len(idx))
        return out

    def _running_sum(self, x: Any) -> np.ndarray:
        if is_str(x):
            raise type_mismatch()
        v = broadcast(x, self.n).astype(np.float64)
        v = np.where(v >= SYS, 0.0, v)
        total = np.cumsum(v)
        base = np.where(self.groups.start > 0, total[self.groups.start - 1], 0.0) if self.n else total
        return total - base


# functions whose result depends on earlier calls (regexs reads the last regexm match): they are
# evaluated observation by observation, in order
_STATEFUL = {"regexm", "regexs"}


def _elementwise(name: str, cols: list[np.ndarray], n: int) -> list:
    """Scalar evaluation of a function with no vectorized form. Each distinct combination of
    arguments is evaluated once (string() of a variable with 50 values over a million
    observations calls the function 50 times, not a million)."""
    if name in _STATEFUL or n < 64:
        return [F.call(name, [c[i] for c in cols]) for i in range(n)]
    lists = [c.tolist() for c in cols]
    cache: dict = {}
    out = []
    append = out.append
    if len(lists) == 1:
        for v in lists[0]:
            r = cache.get(v, cache)
            if r is cache:
                r = cache[v] = F.call(name, [v])
            append(r)
        return out
    for key in zip(*lists):
        r = cache.get(key, cache)
        if r is cache:
            r = cache[key] = F.call(name, list(key))
        append(r)
    return out


# ---------------------------------------------------------------------------
# Evaluation
# ---------------------------------------------------------------------------

def evaluate_vec(node: Node, ctx: VectorContext) -> Any:
    if isinstance(node, Num):
        return node.value
    if isinstance(node, Str):
        return node.value
    if isinstance(node, Name):
        return ctx.name(node.name)
    if isinstance(node, Call):
        if node.name in _RAW_ARG_FUNCS:
            if node.name == "e" and node.raw.strip() == "sample":
                from ..estimation.postest import esample
                return esample(ctx.s).astype(np.float64)
            return ctx.s.context.resolve_result(node.name, node.raw)
        if node.name in MATRIX_FUNCS:
            from ..commands.matrix import matrix_scalar
            return matrix_scalar(ctx.s, node.name, node.args, lambda a: evaluate_vec(a, ctx))
        return ctx.call(node.name, [evaluate_vec(a, ctx) for a in node.args])
    if isinstance(node, Subscript):
        if node.index2 is not None:
            from ..commands.matrix import matrix_element
            return matrix_element(ctx.s, node.name, evaluate_vec(node.index, ctx),
                                  evaluate_vec(node.index2, ctx))
        idx = node.index if isinstance(node.index, str) else evaluate_vec(node.index, ctx)
        return ctx.subscript(node.name, idx)
    if isinstance(node, Unary):
        v = evaluate_vec(node.operand, ctx)
        if node.op == "!":
            t = truth(v)
            return (~t).astype(np.float64) if is_vec(t) else (0.0 if t else 1.0)
        if node.op == "+":
            if is_str(v):
                raise StataError(198, "invalid syntax")
            return v
        if is_str(v):
            raise type_mismatch()
        if not is_vec(v):
            return SYS if M.is_missing(v) else M.normalize(-v)
        return np.where(v >= SYS, SYS, -v)
    if isinstance(node, Binary):
        return binary_vec(node.op, evaluate_vec(node.left, ctx), evaluate_vec(node.right, ctx))
    raise TypeError(node)


def binary_vec(op: str, a: Any, b: Any) -> Any:
    if not is_vec(a) and not is_vec(b):
        return _binary(op, a, b)

    if op in ("&", "|"):
        ta, tb = truth(a), truth(b)
        r = (ta & tb) if op == "&" else (ta | tb)
        return np.asarray(r, dtype=np.float64)

    sa, sb = is_str(a), is_str(b)
    if op == "*" and sa != sb:
        s, k = (a, b) if sa else (b, a)
        n = len(s) if is_vec(s) else len(k)
        ss, kk = broadcast(s, n), broadcast(k, n)
        return np.array(["" if (x >= SYS or x < 1) else t * int(x) for t, x in zip(ss, kk)], dtype=object)
    if sa != sb:
        raise type_mismatch()

    if sa:
        n = len(a) if is_vec(a) else len(b)
        aa, bb = broadcast(a, n), broadcast(b, n)
        if op == "+":
            return np.array([x + y for x, y in zip(aa, bb)], dtype=object)
        cmp = {"==": lambda x, y: x == y, "!=": lambda x, y: x != y, ">": lambda x, y: x > y,
               "<": lambda x, y: x < y, ">=": lambda x, y: x >= y, "<=": lambda x, y: x <= y}.get(op)
        if cmp is None:
            raise type_mismatch()
        return np.array([1.0 if cmp(x, y) else 0.0 for x, y in zip(aa, bb)])

    a, b = _num_arr(a), _num_arr(b)
    if op in ("==", "!=", ">", "<", ">=", "<="):
        r = {"==": np.equal, "!=": np.not_equal, ">": np.greater, "<": np.less,
             ">=": np.greater_equal, "<=": np.less_equal}[op](a, b)
        return np.asarray(r, dtype=np.float64)

    miss = (np.asarray(a) >= SYS) | (np.asarray(b) >= SYS)
    with np.errstate(all="ignore"):
        if op == "+":
            r = np.add(a, b)
        elif op == "-":
            r = np.subtract(a, b)
        elif op == "*":
            r = np.multiply(a, b)
        elif op == "/":
            r = np.divide(a, b)
            miss = miss | (np.asarray(b) == 0)
        elif op == "^":
            aa, bb = np.broadcast_arrays(np.asarray(a, dtype=float), np.asarray(b, dtype=float))
            r = np.power(aa, bb)
            miss = miss | ((aa < 0) & (bb != np.trunc(bb))) | ((aa == 0) & (bb < 0))
        else:
            raise StataError(198, "invalid syntax")
    return _clean(np.asarray(r, dtype=np.float64), miss)


# ---------------------------------------------------------------------------
# Most common vectorized functions (the others fall back to the element-by-element path)
# ---------------------------------------------------------------------------

def _unary_num(fn, domain=None):
    def f(x):
        if is_str(x):
            raise type_mismatch()
        x = np.asarray(x, dtype=np.float64)
        miss = x >= SYS
        if domain is not None:
            miss = miss | ~domain(np.where(miss, 1.0, x))
        with np.errstate(all="ignore"):
            r = fn(np.where(miss, 1.0, x))
        return _clean(np.asarray(r, dtype=np.float64), miss)
    return f


def _round(x, y=1.0):
    if is_str(x) or is_str(y):
        raise type_mismatch()
    x = np.asarray(x, dtype=np.float64)
    y = np.asarray(y, dtype=np.float64)
    miss = (x >= SYS) | (y >= SYS)
    with np.errstate(all="ignore"):
        safe = np.where(y == 0, 1.0, y)
        r = np.where(y == 0, x, np.floor(x / safe + 0.5) * safe)
    return _clean(r, miss)


def _mod(x, y):
    x = np.asarray(x, dtype=np.float64)
    y = np.asarray(y, dtype=np.float64)
    miss = (x >= SYS) | (y >= SYS) | (y == 0)
    with np.errstate(all="ignore"):
        r = x - y * np.floor(x / np.where(y == 0, 1, y))
    return _clean(r, miss)


def _missing(*xs):
    out = None
    for x in xs:
        m = (np.asarray(x, dtype=object) == "") if is_str(x) else (np.asarray(x) >= SYS)
        out = m if out is None else (out | m)
    return np.asarray(out, dtype=np.float64)


def _minmax(fn):
    def f(*xs):
        if any(is_str(x) for x in xs):
            raise type_mismatch()
        n = max(len(x) for x in xs if is_vec(x))
        stack = np.vstack([broadcast(x, n) for x in xs])
        masked = np.where(stack >= SYS, np.nan, stack)
        with np.errstate(all="ignore"):
            import warnings
            with warnings.catch_warnings():
                warnings.simplefilter("ignore", RuntimeWarning)
                r = fn(masked, axis=0)
        return np.where(np.isnan(r), SYS, r)
    return f


def _cond(x, a, b, c=None):
    if is_str(x):
        raise type_mismatch()
    n = max(len(v) for v in (x, a, b, c) if is_vec(v))
    xv = broadcast(x, n)
    out = np.where(xv != 0, broadcast(a, n), broadcast(b, n))
    if c is not None:
        out = np.where(xv >= SYS, broadcast(c, n), out)
    return out.astype(object) if is_str(a) else out.astype(np.float64)


def _inlist(z, *items):
    if any(is_str(i) != is_str(z) for i in items):
        raise type_mismatch()
    zz = np.asarray(z, dtype=object if is_str(z) else np.float64)
    r = np.zeros(zz.shape, dtype=bool)
    for it in items:
        r |= zz == np.asarray(it, dtype=zz.dtype)
    return r.astype(np.float64)


def _inrange(z, a, b):
    if is_str(z):
        return NotImplemented
    z = np.asarray(z, dtype=np.float64)
    a = np.asarray(a, dtype=np.float64)
    b = np.asarray(b, dtype=np.float64)
    lo = np.where(a >= SYS, -np.inf, a)
    r = (z >= lo) & (z <= b) & ((z < SYS) | (b >= SYS))
    return r.astype(np.float64)


def _float(x):
    x = np.asarray(x, dtype=np.float64)
    miss = x >= SYS
    return np.where(miss, x, x.astype(np.float32).astype(np.float64))


def _vnum(fn, domain=None, nargs=None):
    """Vectorized form of a numeric function of several arguments: missing in, missing out;
    outside the domain, missing; NaN and infinities become missing (as functions._num)."""
    def f(*xs):
        if any(is_str(x) for x in xs):
            raise type_mismatch()
        n = max(len(x) for x in xs if is_vec(x))
        arrs = [broadcast(x, n).astype(np.float64, copy=False) for x in xs]
        miss = np.zeros(n, dtype=bool)
        for a in arrs:
            miss |= a >= SYS
        safe = [np.where(miss, 0.5, a) for a in arrs]
        if domain is not None:
            with np.errstate(all="ignore"):
                miss = miss | ~np.asarray(domain(*safe), dtype=bool)
            safe = [np.where(miss, 0.5, a) for a in safe]
        with np.errstate(all="ignore"):
            r = fn(*safe)
        return _clean(np.asarray(r, dtype=np.float64), miss)
    return f


def _st():
    from scipy import stats
    return stats


def _sp():
    from scipy import special
    return special


def _lnfact(x):
    from scipy import special
    return special.gammaln(x + 1)


_RANDOM = {"runiform", "runiformint", "rnormal", "rbinomial", "rpoisson", "rchi2", "rt", "rbeta",
           "rgamma", "rexponential", "rlogistic", "rweibull", "rnbinomial", "rhypergeometric"}

_FAST = {
    "abs": _unary_num(np.abs),
    "sqrt": _unary_num(np.sqrt, lambda x: x >= 0),
    "exp": _unary_num(np.exp),
    "ln": _unary_num(np.log, lambda x: x > 0),
    "log": _unary_num(np.log, lambda x: x > 0),
    "log10": _unary_num(np.log10, lambda x: x > 0),
    "int": _unary_num(np.trunc),
    "trunc": _unary_num(np.trunc),
    "floor": _unary_num(np.floor),
    "ceil": _unary_num(np.ceil),
    "round": _round,
    "mod": _mod,
    "missing": _missing,
    "mi": _missing,
    "min": _minmax(np.nanmin),
    "max": _minmax(np.nanmax),
    "cond": _cond,
    "inlist": _inlist,
    "inrange": _inrange,
    "float": _float,
    "sin": _vnum(np.sin),
    "cos": _vnum(np.cos),
    "tan": _vnum(np.tan),
    "asin": _vnum(np.arcsin, lambda x: np.abs(x) <= 1),
    "acos": _vnum(np.arccos, lambda x: np.abs(x) <= 1),
    "atan": _vnum(np.arctan),
    "atan2": _vnum(np.arctan2),
    "sinh": _vnum(np.sinh),
    "cosh": _vnum(np.cosh),
    "tanh": _vnum(np.tanh),
    "sign": _vnum(np.sign),
    "lngamma": _vnum(lambda x: _sp().gammaln(x), lambda x: x > 0),
    "lnfactorial": _vnum(_lnfact, lambda x: (x >= 0) & (x == np.trunc(x))),
    "logit": _vnum(lambda p: np.log(p / (1 - p)), lambda p: (p > 0) & (p < 1)),
    "invlogit": _vnum(lambda x: np.where(x > -700, 1 / (1 + np.exp(-np.maximum(x, -700))), 0.0)),
    "digamma": _vnum(lambda x: _sp().digamma(x)),
    "normal": _vnum(lambda z: _st().norm.cdf(z)),
    "normalden": _vnum(lambda z, m=0.0, s=1.0: _st().norm.pdf(z, m, s), lambda z, m=0.0, s=1.0: s > 0),
    "invnormal": _vnum(lambda p: _st().norm.ppf(p), lambda p: (p > 0) & (p < 1)),
    "lnnormal": _vnum(lambda z: _st().norm.logcdf(z)),
    "chi2": _vnum(lambda df, x: _st().chi2.cdf(x, df), lambda df, x: df > 0),
    "chi2tail": _vnum(lambda df, x: _st().chi2.sf(x, df), lambda df, x: df > 0),
    "invchi2": _vnum(lambda df, p: _st().chi2.ppf(p, df), lambda df, p: (p >= 0) & (p < 1)),
    "invchi2tail": _vnum(lambda df, p: _st().chi2.isf(p, df), lambda df, p: (p > 0) & (p <= 1)),
    "F": _vnum(lambda d1, d2, f: _st().f.cdf(f, d1, d2)),
    "Ftail": _vnum(lambda d1, d2, f: _st().f.sf(f, d1, d2)),
    "invF": _vnum(lambda d1, d2, p: _st().f.ppf(p, d1, d2), lambda d1, d2, p: (p >= 0) & (p < 1)),
    "invFtail": _vnum(lambda d1, d2, p: _st().f.isf(p, d1, d2), lambda d1, d2, p: (p > 0) & (p <= 1)),
    "t": _vnum(lambda df, t: _st().t.cdf(t, df)),
    "ttail": _vnum(lambda df, t: _st().t.sf(t, df)),
    "invt": _vnum(lambda df, p: _st().t.ppf(p, df), lambda df, p: (p > 0) & (p < 1)),
    "invttail": _vnum(lambda df, p: _st().t.isf(p, df), lambda df, p: (p > 0) & (p < 1)),
    "binomial": _vnum(lambda n, k, p: _st().binom.cdf(k, n, p)),
    "binomialtail": _vnum(lambda n, k, p: _st().binom.sf(k - 1, n, p)),
    "poisson": _vnum(lambda m, k: _st().poisson.cdf(k, m)),
    "poissontail": _vnum(lambda m, k: _st().poisson.sf(k - 1, m)),
    "betaden": _vnum(lambda a, b, x: _st().beta.pdf(x, a, b)),
    "ibeta": _vnum(lambda a, b, x: _sp().betainc(a, b, x)),
    "gammap": _vnum(lambda a, x: _sp().gammainc(a, x)),
}

