"""Mata's associative arrays (asarray) and optimization (optimize).

optimize() follows [M-5] optimize(): d0, d1 and d2 evaluators (function,
gradient and Hessian), nr (Newton–Raphson) and bfgs techniques, maximization or
minimization, ptol, vtol and nrtol convergence criteria. Numerical
derivatives use central differences; Stata's steps are not
documented, so the values of each iteration may differ in the last
digits (VERIFY the iteration log in compat/do/0406_mata_optimize.do).
"""

from __future__ import annotations

import numpy as np

from ..core.formats import format_value
from .libbase import lib
from .values import MV, MataError, SYS, empty, real, string


class AssocArray:
    def __init__(self, keytype: str, keydim: int):
        self.keytype = keytype
        self.keydim = keydim
        self.data: dict = {}
        self.notfound: MV = empty("real", 0, 0)


def _box(obj) -> MV:
    arr = np.empty((1, 1), dtype=object)
    arr[0, 0] = obj
    return MV(arr, "struct")


def _unbox(v: MV, cls):
    obj = v.a[0, 0] if v.a.size == 1 else None
    if not isinstance(obj, cls):
        raise MataError(3000, "invalid argument")   # VERIFY
    return obj


def _key(A: AssocArray, k: MV):
    vals = k.a.ravel().tolist()
    if len(vals) != A.keydim:
        raise MataError(3200, "conformability error")
    return tuple(str(x) if k.t == "string" else float(x) for x in vals)


@lib("asarray_create", 0, 3)
def _asarray_create(eng, v, r):
    keytype = v[0].str_scalar() if v and v[0] is not None else "string"
    keydim = v[1].int_scalar() if len(v) > 1 and v[1] is not None else 1
    return _box(AssocArray(keytype, keydim))


@lib("asarray", 2, 3)
def _asarray(eng, v, r):
    A = _unbox(v[0], AssocArray)
    key = _key(A, v[1])
    if len(v) == 3:
        A.data[key] = v[2].copy()
        return None
    return A.data.get(key, A.notfound).copy()


@lib("asarray_contains", 2)
def _asarray_contains(eng, v, r):
    A = _unbox(v[0], AssocArray)
    return real(1.0 if _key(A, v[1]) in A.data else 0.0)


@lib("asarray_remove", 2)
def _asarray_remove(eng, v, r):
    A = _unbox(v[0], AssocArray)
    A.data.pop(_key(A, v[1]), None)
    return None


@lib("asarray_elements", 1)
def _asarray_elements(eng, v, r):
    return real(float(len(_unbox(v[0], AssocArray).data)))


@lib("asarray_keys", 1)
def _asarray_keys(eng, v, r):
    A = _unbox(v[0], AssocArray)
    keys = sorted(A.data)          # VERIFY: Stata returns them in hash order
    if A.keytype == "string":
        out = np.empty((len(keys), A.keydim), dtype=object)
        for i, k in enumerate(keys):
            out[i, :] = list(k)
        return MV(out, "string") if keys else empty("string", 0, A.keydim)
    return real(np.array(keys, dtype=np.float64).reshape(len(keys), A.keydim))


@lib("asarray_notfound", 1, 2)
def _asarray_notfound(eng, v, r):
    A = _unbox(v[0], AssocArray)
    if len(v) == 1:
        return A.notfound.copy()
    A.notfound = v[1].copy()
    return None


# ---------------------------------------------------------------------------
# optimize()
# ---------------------------------------------------------------------------

class OptState:
    def __init__(self):
        self.evaluator: str | None = None
        self.evaltype = "d0"
        self.params: np.ndarray | None = None
        self.which = "max"
        self.technique = "nr"
        self.args: dict[int, MV] = {}
        self.trace = "value"
        self.maxiter = 300
        self.ptol, self.vtol, self.nrtol = 1e-6, 1e-7, 1e-5
        self.result: dict = {}


def _state(v: MV) -> OptState:
    return _unbox(v, OptState)


@lib("optimize_init", 0)
def _optimize_init(eng, v, r):
    return _box(OptState())


@lib("optimize_init_evaluator", 1, 2)
def _opt_evaluator(eng, v, r):
    S = _state(v[0])
    if len(v) == 1:
        return string(S.evaluator or "")
    p = v[1]
    if p.t != "pointer" or p.scalar() is None:
        raise MataError(3000, "function pointer required")   # VERIFY
    target = p.scalar().get()
    if not isinstance(target, str):
        raise MataError(3000, "function pointer required")
    S.evaluator = target
    return None


def _setter(attr, conv):
    def f(eng, v, r):
        S = _state(v[0])
        if len(v) == 1:
            val = getattr(S, attr)
            return string(val) if isinstance(val, str) else real(float(val))
        setattr(S, attr, conv(v[1]))
        return None
    return f


lib("optimize_init_evaluatortype", 1, 2)(_setter("evaltype", lambda x: x.str_scalar()))
lib("optimize_init_which", 1, 2)(_setter("which", lambda x: x.str_scalar()))
lib("optimize_init_technique", 1, 2)(_setter("technique", lambda x: x.str_scalar().split()[0]))
lib("optimize_init_tracelevel", 1, 2)(_setter("trace", lambda x: x.str_scalar()))
lib("optimize_init_conv_maxiter", 1, 2)(_setter("maxiter", lambda x: x.int_scalar()))
lib("optimize_init_conv_ptol", 1, 2)(_setter("ptol", lambda x: x.real_scalar()))
lib("optimize_init_conv_vtol", 1, 2)(_setter("vtol", lambda x: x.real_scalar()))
lib("optimize_init_conv_nrtol", 1, 2)(_setter("nrtol", lambda x: x.real_scalar()))


@lib("optimize_init_params", 1, 2)
def _opt_params(eng, v, r):
    S = _state(v[0])
    if len(v) == 1:
        return real(S.params.reshape(1, -1)) if S.params is not None else empty("real", 0, 0)
    S.params = v[1].a.astype(np.float64).ravel().copy()
    return None


@lib("optimize_init_argument", 3)
def _opt_argument(eng, v, r):
    S = _state(v[0])
    S.args[v[1].int_scalar()] = v[2].copy()
    return None


@lib("optimize_init_narguments", 1, 2)
def _opt_nargs(eng, v, r):
    S = _state(v[0])
    if len(v) == 1:
        return real(float(len(S.args)))
    return None


def _evaluate(eng, S: OptState, p: np.ndarray, todo: int):
    """Calls the evaluator: f(todo, p, args..., v, g, H) and returns (v, g, H)."""
    f = eng.funcs.get(S.evaluator or "")
    if f is None:
        raise MataError(3499, f"{S.evaluator}() not found")
    extra = [S.args[k] for k in sorted(S.args)]
    values = [real(float(todo)), real(p.reshape(1, -1))] + extra + [real(SYS), real(SYS), real(SYS)]
    out = eng.call_with_values(f, values)
    n = len(values)
    vv, gg, HH = out[n - 3], out[n - 2], out[n - 1]
    val = float(vv.a.ravel()[0]) if vv is not None and vv.a.size else SYS
    g = gg.a.astype(np.float64).ravel() if todo >= 1 and gg is not None and gg.a.size == p.size else None
    H = HH.a.astype(np.float64) if todo >= 2 and HH is not None and HH.a.shape == (p.size, p.size) else None
    return val, g, H


def _deltas(fun, p: np.ndarray, f0: float, second: bool = False) -> np.ndarray:
    """Steps of the numerical derivatives, as described in [M-5] deriv(): d = h*scale,
    h = (|p| + 1e-3)*1e-3, and the scale is searched until |f(p) - f(p - d)| falls
    between v0 = (|f|+1e-8)*1e-8 and v1 = (|f|+1e-7)*1e-7.
    The scale moves in powers of 10 from 1: with scale 0.1 OpenDTA
    reproduces the standard errors of the d1 logit of compat 0406 to the last digit.
    VERIFY: when a jump of 10 crosses the interval, Stata interpolates
    (undocumented); here, bisection on the log scale between the two sides.
    `second`: steps of the Hessian of a d0 evaluator, searched through the second
    difference |f(p+d) - 2f(p) + f(p-d)|; with this the iteration path of
    compat 0406 (d0) matches Stata's. VERIFY the criterion."""
    v0 = (abs(f0) + 1e-8) * 1e-8
    v1 = (abs(f0) + 1e-7) * 1e-7
    out = np.empty_like(p)

    def diff_at(i, scale, h):
        q = p.copy()
        q[i] -= h * scale
        if second:
            a = p.copy()
            a[i] += h * scale
            v = abs(fun(a) - 2 * f0 + fun(q))
        else:
            v = abs(f0 - fun(q))
        return v if np.isfinite(v) else np.inf

    for i in range(p.size):
        h = (abs(p[i]) + 1e-3) * 1e-3
        scale = 1.0
        d = diff_at(i, scale, h)
        lo = hi = None                 # scales with difference < v0 and > v1
        for _ in range(40):
            if v0 <= d <= v1:
                break
            if d < v0:
                lo = scale
            else:
                hi = scale
            scale = (lo * hi) ** 0.5 if lo is not None and hi is not None else \
                (scale * 10 if d < v0 else scale / 10)
            d = diff_at(i, scale, h)
        out[i] = h * scale
    return out


def _richardson(D, h: float) -> float:
    """Richardson extrapolation of a central difference: (4 D(h/2) - D(h)) / 3
    removes the order-h² term of the error (set numerics precise)."""
    return (4 * D(h / 2) - D(h)) / 3


def _num_grad_precise(fun, p: np.ndarray, f0: float) -> np.ndarray:
    g = np.zeros_like(p)
    for i in range(p.size):
        h = 1e-3 * (abs(p[i]) + 1)

        def D(hh, i=i):
            a, b = p.copy(), p.copy()
            a[i] += hh
            b[i] -= hh
            return (fun(a) - fun(b)) / (2 * hh)
        g[i] = _richardson(D, h)
    return g


def _num_hess_precise(fun, grad, p: np.ndarray, analytic_grad: bool) -> np.ndarray:
    k = p.size
    H = np.zeros((k, k))
    hs = 1e-3 * (np.abs(p) + 1)
    if analytic_grad:
        for i in range(k):
            def D(hh, i=i):
                a, b = p.copy(), p.copy()
                a[i] += hh
                b[i] -= hh
                return (grad(a) - grad(b)) / (2 * hh)
            H[:, i] = _richardson(D, hs[i])
        return (H + H.T) / 2
    f0 = fun(p)
    for i in range(k):
        for j in range(i, k):
            if i == j:
                def D(hh, i=i):
                    a, b = p.copy(), p.copy()
                    a[i] += hh
                    b[i] -= hh
                    return (fun(a) - 2 * f0 + fun(b)) / hh ** 2
                H[i, i] = _richardson(D, hs[i])
            else:
                def D(hh, i=i, j=j):
                    r = hh / hs[i]
                    hi, hj = hs[i] * r, hs[j] * r
                    pp, pm, mp, mm = (p.copy() for _ in range(4))
                    pp[i] += hi; pp[j] += hj          # noqa: E702
                    pm[i] += hi; pm[j] -= hj          # noqa: E702
                    mp[i] -= hi; mp[j] += hj          # noqa: E702
                    mm[i] -= hi; mm[j] -= hj          # noqa: E702
                    return (fun(pp) - fun(pm) - fun(mp) + fun(mm)) / (4 * hi * hj)
                H[i, j] = H[j, i] = _richardson(D, hs[i])
    return H


def _num_grad(fun, p: np.ndarray, f0: float | None = None) -> np.ndarray:
    f0 = fun(p) if f0 is None else f0
    from ..estimation.numerics import precise
    if precise():
        return _num_grad_precise(fun, p, f0)
    d = _deltas(fun, p, f0)
    g = np.zeros_like(p)
    for i in range(p.size):
        a, b = p.copy(), p.copy()
        a[i] += d[i]
        b[i] -= d[i]
        g[i] = (fun(a) - fun(b)) / (2 * d[i])
    return g


def _num_hess(fun, grad, p: np.ndarray, analytic_grad: bool = False) -> np.ndarray:
    """Numerical Hessian: central differences of the gradient (d1 evaluator) or
    second differences of the function (d0), with the steps from _deltas()."""
    from ..estimation.numerics import precise
    if precise():
        return _num_hess_precise(fun, grad, p, analytic_grad)
    k = p.size
    H = np.zeros((k, k))
    f0 = fun(p)
    d = _deltas(fun, p, f0, second=not analytic_grad)
    if analytic_grad:
        for i in range(k):
            a, b = p.copy(), p.copy()
            a[i] += d[i]
            b[i] -= d[i]
            H[:, i] = (grad(a) - grad(b)) / (2 * d[i])
        return (H + H.T) / 2
    for i in range(k):
        for j in range(i, k):
            if i == j:
                a, b = p.copy(), p.copy()
                a[i] += d[i]
                b[i] -= d[i]
                H[i, i] = (fun(a) - 2 * f0 + fun(b)) / d[i] ** 2
            else:
                pp, pm, mp, mm = (p.copy() for _ in range(4))
                pp[i] += d[i]; pp[j] += d[j]          # noqa: E702
                pm[i] += d[i]; pm[j] -= d[j]          # noqa: E702
                mp[i] -= d[i]; mp[j] += d[j]          # noqa: E702
                mm[i] -= d[i]; mm[j] -= d[j]          # noqa: E702
                H[i, j] = H[j, i] = (fun(pp) - fun(pm) - fun(mp) + fun(mm)) / (4 * d[i] * d[j])
    return H


@lib("optimize", 1)
def _optimize(eng, v, r):
    S = _state(v[0])
    if S.params is None:
        raise MataError(111, "initial values not set")   # VERIFY
    sign = 1.0 if S.which == "max" else -1.0
    order = {"d0": 0, "d1": 1, "d2": 2}.get(S.evaltype.lower().replace("debug", ""), 0)

    def fval(p):
        return sign * _evaluate(eng, S, p, 0)[0]

    def grad(p):
        if order >= 1:
            _, g, _ = _evaluate(eng, S, p, 1)
            if g is not None:
                return sign * g
        return _num_grad(fval, p)

    def hess(p):
        if order >= 2:
            _, _, H = _evaluate(eng, S, p, 2)
            if H is not None:
                return sign * H
        return _num_hess(fval, grad, p, analytic_grad=order >= 1)

    out = eng.s.output
    p = S.params.astype(np.float64).copy()
    f = fval(p)
    if f >= SYS or not np.isfinite(f):
        raise MataError(3498, "could not calculate numerical derivatives -- missing values encountered")
    converged = False
    it = 0
    Binv = np.eye(p.size)
    g = grad(p)
    while True:
        concave = True
        if S.technique == "bfgs":
            step = Binv @ g
        else:
            H = hess(p)
            try:
                np.linalg.cholesky(-H)
            except np.linalg.LinAlgError:
                concave = False
            Hm = H.copy()
            if not concave:
                # forces negative definiteness by adding a multiple of the identity
                lam = max(1e-8, float(np.max(np.linalg.eigvalsh(H))) * 1.1 + 1e-6)
                Hm = H - lam * np.eye(p.size)
            step = -np.linalg.solve(Hm, g)
        if S.trace != "none":
            note = "  (not concave)" if not concave else ""
            out.write(f"Iteration {it}:   f(p) = {format_value(sign * f, '%10.0g', pad=False).strip():>10}{note}\n",
                      "text")
        if it >= S.maxiter:
            break
        # step with backtracking (step halving); if the full step improves, it advances in
        # increments of 1/8, 1/4, 1/2... of the step while it improves. VERIFY: rule deduced from
        # Stata's log (compat 0406: steps of 1.375 and 1.125 in the logit); the manual only says
        # "forward"/"backward"
        t = 1.0
        for _ in range(60):
            pn = p + t * step
            fn = fval(pn)
            if fn < SYS and np.isfinite(fn) and fn >= f - 1e-12 * max(1.0, abs(f)):
                break
            t /= 2
        else:
            break
        if t == 1.0 and fn > f:
            inc = 0.125
            for _ in range(60):
                pt = p + (t + inc) * step
                ft = fval(pt)
                if not (ft < SYS and np.isfinite(ft) and ft > fn):
                    break
                t, pn, fn = t + inc, pt, ft
                inc *= 2
        gn = grad(pn)
        if S.technique == "bfgs":
            s_ = pn - p
            y = -(gn - g)
            sy = float(s_ @ y)
            if sy > 1e-12:
                rho = 1 / sy
                Id = np.eye(p.size)
                Binv = (Id - rho * np.outer(s_, y)) @ Binv @ (Id - rho * np.outer(y, s_)) + rho * np.outer(s_, s_)
        dp = np.max(np.abs(pn - p) / (np.abs(p) + 1))
        dv = abs(fn - f) / (abs(f) + 1)
        p, f, g = pn, fn, gn
        it += 1
        try:
            Hc = hess(p) if S.technique != "bfgs" else -np.linalg.inv(Binv)
            nr = float(abs(g @ np.linalg.solve(Hc, g)))
        except np.linalg.LinAlgError:
            nr = np.inf
        if (dp < S.ptol or dv < S.vtol) and nr < S.nrtol:
            converged = True
            if S.trace != "none":
                out.write(f"Iteration {it}:   f(p) = {format_value(sign * f, '%10.0g', pad=False).strip():>10}\n",
                          "text")
            break
    from ..estimation.numerics import precise
    if converged and precise() and S.technique != "bfgs":
        # extra Newton steps, outside the log, while the gradient decreases
        for _ in range(5):
            try:
                pn = p - np.linalg.solve(hess(p), g)
            except np.linalg.LinAlgError:
                break
            fn = fval(pn)
            gn = grad(pn)
            if not np.isfinite(fn) or fn < f - 1e-12 * max(1.0, abs(f)) or \
                    np.linalg.norm(gn) >= np.linalg.norm(g):
                break
            p, f, g = pn, fn, gn
    H = hess(p)
    try:
        V = np.linalg.inv(-H)
        V = (V + V.T) / 2              # symmetric, like Stata's
    except np.linalg.LinAlgError:
        V = np.full(H.shape, SYS)
    S.params = p
    S.result = {"params": p, "value": sign * f, "gradient": sign * g, "H": sign * H, "V": V,
                # Stata counts iteration 0 (compat 0406: log 0..2 and 3 iterations)
                "iterations": it + 1, "converged": converged}   # VERIFY
    return real(p.reshape(1, -1))


def _result(key):
    def f(eng, v, r):
        S = _state(v[0])
        if key not in S.result:
            raise MataError(3498, "optimize() has not been run")   # VERIFY
        x = S.result[key]
        if isinstance(x, bool):
            return real(1.0 if x else 0.0)
        if isinstance(x, (int, float)):
            return real(float(x))
        x = np.asarray(x, dtype=np.float64)
        return real(x.reshape(1, -1) if x.ndim == 1 else x)
    return f


lib("optimize_result_params", 1)(_result("params"))
lib("optimize_result_value", 1)(_result("value"))
lib("optimize_result_gradient", 1)(_result("gradient"))
lib("optimize_result_Hessian", 1)(_result("H"))
lib("optimize_result_V", 1)(_result("V"))
lib("optimize_result_iterations", 1)(_result("iterations"))
lib("optimize_result_converged", 1)(_result("converged"))

files.opendta/mata/display.py:
"""Display of Mata results (what appears when an expression is typed).

Scalar: two spaces and the value. Matrix: column numbers centered
over each column, a box with +---+ and the number of each row:

           1   2
        +---------+
      1 |  1   2  |
      2 |  3   4  |
        +---------+

All columns are as wide as the largest element of the matrix, with the column
number right-aligned over it; numbers use %12.0g
(observed in Stata 14, compat 0401 and 0403).
Symmetric matrices appear as [symmetric], with only the lower
triangle. Details marked VERIFY have cases in compat/do/04*.do.
"""

from __future__ import annotations

import numpy as np

from ..core import missing as M
from ..core.formats import format_value
from .values import MV, Pointer

REAL_FORMAT = "%12.0g"     # observed in Stata 14: 1/3 → .3333333333, 1e10 → 1.00000e+10


def cell(x, t: str) -> str:
    if t == "real":
        x = float(x)
        if x >= M.SYSMISS:
            return M.missing_name(x)
        return format_value(x, REAL_FORMAT, pad=False).strip()
    if t == "string":
        return str(x)
    if t == "complex":
        z = complex(x)
        re_ = format_value(z.real, REAL_FORMAT, pad=False).strip()
        im = format_value(abs(z.imag), REAL_FORMAT, pad=False).strip()
        return f"{re_} {'-' if z.imag < 0 else '+'} {im}i"
    if t == "pointer":
        if x is None:
            return "NULL"
        return f"0x{id(x) & 0xffffffff:x}"
    if t == "struct":
        return f"0x{id(x) & 0xffffffff:x}"
    return str(x)


def _symmetric(v: MV) -> bool:
    if v.t != "real" or v.rows != v.cols or v.rows < 2:
        return False
    return bool(np.array_equal(v.a, v.a.T))


def render(v: MV) -> list[str]:
    r, c = v.a.shape
    if r == 0 or c == 0:
        return []
    if r == 1 and c == 1:
        return ["  " + cell(v.a[0, 0], v.t)]
    sym = _symmetric(v)
    texts = [[cell(v.a[i, j], v.t) if (not sym or j <= i) else "" for j in range(c)] for i in range(r)]
    w_all = max(1, max(len(texts[i][j]) for i in range(r) for j in range(c)))
    widths = [w_all] * c
    lab_w = max(3, len(str(r)))
    lead = lab_w + 4                 # "  1 |" + 2 spaces before the 1st column
    lines: list[str] = []
    if sym:
        lines.append("[symmetric]")
    head = [" "] * (lead + sum(widths) + 3 * (c - 1) + 2)
    pos = lead
    for j, w in enumerate(widths):
        lab = str(j + 1)
        start = pos + w - len(lab)
        for k, ch in enumerate(lab):
            if 0 <= start + k < len(head):
                head[start + k] = ch
        pos += w + 3
    lines.append("".join(head).rstrip())
    inner = 2 + sum(widths) + 3 * (c - 1) + 2
    bar = " " * (lab_w + 1) + "+" + "-" * inner + "+"
    lines.append(bar)
    for i in range(r):
        body = "   ".join(texts[i][j].rjust(widths[j]) for j in range(c))
        lines.append(f"{i + 1:>{lab_w}} |  {body}  |")
    lines.append(bar)
    return lines


def is_displayable(v) -> bool:
    return isinstance(v, MV) and not isinstance(v.a, Pointer)

